import React, { createContext, useCallback, useContext, useMemo, useState } from 'react';

const NotificationContext = createContext();

let nextId = 0;

const typeStyles = {
  success: {
    accent: 'border-l-emerald-500',
    icon: (
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="h-5 w-5 text-emerald-600">
        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.857-9.809a.75.75 0 00-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 10-1.06 1.061l2.5 2.5a.75.75 0 001.137-.089l4-5.5z" clipRule="evenodd" />
      </svg>
    ),
  },
  error: {
    accent: 'border-l-red-500',
    icon: (
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="h-5 w-5 text-red-600">
        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-8-5a.75.75 0 01.75.75v4.5a.75.75 0 01-1.5 0v-4.5A.75.75 0 0110 5zm0 10a1 1 0 100-2 1 1 0 000 2z" clipRule="evenodd" />
      </svg>
    ),
  },
  warning: {
    accent: 'border-l-amber-500',
    icon: (
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="h-5 w-5 text-amber-600">
        <path fillRule="evenodd" d="M8.485 2.495c.673-1.167 2.357-1.167 3.03 0l6.28 10.875c.673 1.167-.17 2.625-1.516 2.625H3.72c-1.347 0-2.189-1.458-1.515-2.625L8.485 2.495zM10 6a.75.75 0 01.75.75v3.5a.75.75 0 01-1.5 0v-3.5A.75.75 0 0110 6zm0 9a1 1 0 100-2 1 1 0 000 2z" clipRule="evenodd" />
      </svg>
    ),
  },
  info: {
    accent: 'border-l-blue-500',
    icon: (
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="h-5 w-5 text-blue-600">
        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a.75.75 0 000 1.5h.253a.25.25 0 01.244.304l-.459 2.066A1.75 1.75 0 0010.747 15H11a.75.75 0 000-1.5h-.253a.25.25 0 01-.244-.304l.459-2.066A1.75 1.75 0 009.253 9H9z" clipRule="evenodd" />
      </svg>
    ),
  },
};

const DEFAULT_DURATION = 3500;

export const NotificationProvider = ({ children }) => {
  const [notifications, setNotifications] = useState([]);

  const dismiss = useCallback((id) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, []);

  const notify = useCallback(
    (type, message, options = {}) => {
      const id = `notif-${++nextId}`;
      const duration = options.duration ?? DEFAULT_DURATION;
      const entry = { id, type, message, title: options.title || '' };

      setNotifications((prev) => [...prev, entry]);

      if (duration > 0) {
        setTimeout(() => dismiss(id), duration);
      }

      return id;
    },
    [dismiss],
  );

  const notifySuccess = useCallback((msg, opts) => notify('success', msg, opts), [notify]);
  const notifyError = useCallback((msg, opts) => notify('error', msg, opts), [notify]);
  const notifyWarning = useCallback((msg, opts) => notify('warning', msg, opts), [notify]);
  const notifyInfo = useCallback((msg, opts) => notify('info', msg, opts), [notify]);

  const value = useMemo(
    () => ({ notify, notifySuccess, notifyError, notifyWarning, notifyInfo, dismiss }),
    [notify, notifySuccess, notifyError, notifyWarning, notifyInfo, dismiss],
  );

  return (
    <NotificationContext.Provider value={value}>
      {children}

      {/* Notification container */}
      <div className="fixed right-4 top-4 z-[100] flex w-[min(420px,calc(100vw-2rem))] flex-col gap-3 pointer-events-none">
        {notifications.map((n) => {
          const style = typeStyles[n.type] || typeStyles.info;
          return (
            <div
              key={n.id}
              className={`pointer-events-auto animate-slide-in rounded-2xl border border-gray-200 border-l-4 ${style.accent} bg-white p-4 shadow-lg shadow-gray-200/70`}
            >
              <div className="flex items-start gap-3">
                <span className="mt-0.5 shrink-0">{style.icon}</span>
                <div className="min-w-0 flex-1">
                  {n.title && <p className="text-sm font-semibold text-gray-900">{n.title}</p>}
                  <p className={`text-sm text-gray-600 ${n.title ? 'mt-0.5' : ''}`}>{n.message}</p>
                </div>
                <button
                  type="button"
                  onClick={() => dismiss(n.id)}
                  className="shrink-0 rounded-lg p-1 text-gray-400 hover:bg-gray-100 hover:text-gray-600"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="h-4 w-4">
                    <path d="M6.28 5.22a.75.75 0 00-1.06 1.06L8.94 10l-3.72 3.72a.75.75 0 101.06 1.06L10 11.06l3.72 3.72a.75.75 0 101.06-1.06L11.06 10l3.72-3.72a.75.75 0 00-1.06-1.06L10 8.94 6.28 5.22z" />
                  </svg>
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </NotificationContext.Provider>
  );
};

export const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotification must be used within a NotificationProvider');
  }
  return context;
};
